insert into survey_pay_info_detail_new (pay_id, opr_id, opr_code
  )
values (#{payId,jdbcType=BIGINT}, #{oprId,jdbcType=BIGINT}, #{oprCode,jdbcType=VARCHAR}
  )

mapper.update:
update survey_pay_info_detail_new
set pay_id = #{payId,jdbcType=BIGINT},
  opr_id = #{oprId,jdbcType=BIGINT},
  opr_code = #{oprCode,jdbcType=VARCHAR}
where id = #{id,jdbcType=BIGINT}

update fina_settlement_info a
left join survey_pay_info_detail_new d on a.id = d.opr_id and d.opr_code = 'settlement'
set a.finsh_account_time = now(),finsh_close_time = now(),settlement_state = #{settlementState}
where d.id is not null and d.pay_id = #{billId,jdbcType=BIGINT}

mapper.select:
select a.id from fina_settlement_info a
left join survey_pay_info_detail_new d on a.id = d.opr_id and d.opr_code = 'settlement'
where d.id is not null and d.pay_id = #{billId,jdbcType=BIGINT}
